const Fastify = require('./fastify.js')
const Ajv = require('ajv')

for (const coerceTypes of [true, 'array', false]) {
  const ajv = new Ajv({ coerceTypes })
  const v = ajv.compile({ type: 'object', properties: { length: { anyOf: [{ type: 'null' }, { type: 'number' }] } } })
  const data = { length: 0 }
  console.log('ajv coerceTypes=' + coerceTypes, 'valid:', v(data), 'data:', JSON.stringify(data))
}

async function run (opts) {
  const f = Fastify(opts)
  f.addSchema({ $id: 'MyModel', type: 'object', properties: { length: { anyOf: [{ type: 'null' }, { type: 'number' }] } } })
  f.post('/', { schema: { body: { $ref: 'MyModel' } } }, (req) => req.body)
  const r = await f.inject({ method: 'POST', url: '/', payload: { length: 0 } })
  console.log('fastify', JSON.stringify(opts), '->', r.body)
}

run({}).then(() => run({ ajv: { customOptions: { coerceTypes: false } } }))

