'use strict'

const { test } = require('node:test')
const Fastify = require('..')

test('validator returning a falsy value should update the request param', async (t) => {
  const fastify = Fastify()

  // a validator that coerces the payload to the value of its `coerceTo` property
  fastify.setValidatorCompiler(() => {
    return (data) => {
      if (typeof data === 'object' && data !== null && 'coerceTo' in data) {
        return { value: data.coerceTo }
      }
      return true
    }
  })

  fastify.post('/test', { schema: { body: { type: 'object' } } }, (request, reply) => {
    reply.send({ body: request.body })
  })

  for (const value of [0, '', false, null]) {
    const res = await fastify.inject({
      method: 'POST',
      url: '/test',
      payload: { coerceTo: value }
    })

    t.assert.strictEqual(res.statusCode, 200)
    t.assert.strictEqual(JSON.parse(res.payload).body, value, `should update body to ${JSON.stringify(value)}`)
  }
})

test('validator returning a truthy non-object should not touch the request param', async (t) => {
  const fastify = Fastify()

  fastify.setValidatorCompiler(() => () => true)

  fastify.post('/test', { schema: { body: { type: 'object' } } }, (request, reply) => {
    reply.send({ body: request.body })
  })

  const res = await fastify.inject({
    method: 'POST',
    url: '/test',
    payload: { length: 0 }
  })

  t.assert.strictEqual(res.statusCode, 200)
  t.assert.deepStrictEqual(JSON.parse(res.payload).body, { length: 0 })
})

